<script>
  export default {
    data(){
      return{
        show: false,
        amount: 0,
        unique: 0
      }
    },
    methods: {
      handleClose() {
        this.show = false
      },
      doOpen(){
        this.show = true
      }
    },
    created() {
      this.amount = localStorage.getItem('count') || 0;
      let spottedList = localStorage.getItem('spottedList')
        try {
          let spottedListArr = JSON.parse(spottedList);
          this.unique = spottedListArr.length;
        } catch (err) {
          this.unique = 0
        }
        this.$forceUpdate();
    }
  }
</script>

<template>
<el-dialog :visible="show" :beforeClose="handleClose" title="Statistic">
  <div>
    <p>For now, the little cherry meow said "Trick or Treat" {{amount}} times!</p>
    <p>And had spotted {{unique}} possible costumes!</p>
    <p v-if="unique !== 5">Actually there are more possibilities, try finding them all...</p>
    <p v-else>You've found all costumes this mystery potion can provide!</p>
  </div>

  <span slot="footer" class="dialog-footer">
    <el-button @click="handleClose">Close</el-button>
  </span>
</el-dialog>
</template>

