<script>
import aboutPopup from '@/components/aboutPopup.vue'
import progressPopup from '@/components/progressPopup.vue'
export default {
  name: "ClickPotion",
  props: {},
  components: {
    aboutPopup,
    progressPopup
  },
  data() {
    return {
      potionArray: [
        {
          id: 1,
          name: "hell",
          color: "#EE771B",
        },
        {
          id: 2,
          name: "witch",
          color: "#A1529B",
        },
        {
          id: 3,
          name: "devil",
          color: "#CD2E19",
        },
        {
          id: 4,
          name: "zombie",
          color: "#7BBD26",
        },
        {
          id: 5,
          name: "ghost",
          color: "#00AFCC",
        },
      ],
      chosen: "",
      isChosen: false,
      spottedList: []
    };
  },
  methods: {
    beginRandomChoose() {
      const randomIndex = Math.floor(Math.random() * this.potionArray.length);
      this.chosen = randomIndex;
      this.isChosen = true;
      sessionStorage.setItem("chosen", randomIndex);
      sessionStorage.setItem("isChosen", true);
      console.log("Chosen potion index:", randomIndex);
      console.log(this.$isChosen);
      this.$forceUpdate(); // Force re-render to reflect changes
      setTimeout(() => {
        if (this.spottedList.indexOf(randomIndex) < 0) {
          this.spottedList.push(randomIndex);
          localStorage.setItem('spottedList', JSON.stringify(this.spottedList))
        }
        let amount = !isNaN(localStorage.getItem('count'))?  localStorage.getItem('count') : 0;
        amount = parseInt(amount)
        amount+=1;
        localStorage.setItem('count', amount)
        this.$router.replace("/result");
      }, 3000);
    },
    openAbout(){
      this.$refs.popup.doOpen();
    },
    openProg(){
      this.$refs.prog.doOpen();
    },
    openQuit(){
      var r=confirm("Are you sure you want to quit?");
      if (r){
        window.history.back();
      }
    },
    doOpenSound(){
      this.$emit('openSound', false)
    }
  },
  created() {
    let spottedList = localStorage.getItem('spottedList')
    if (spottedList.length > 0) {
      try {
        this.spottedList = JSON.parse(spottedList)
      } catch (err) {
        this.spottedList = [];
      }
    }
  },
  mounted() {
    setTimeout(() => {
      document.getElementById('potionBox').style.opacity = 0
    }, 0)
    setTimeout(() => {
      document.getElementById('potionBox').style.display = 'none'
    }, 500)
  }
};
</script>

